# Arregla el repositorio DetectionLab en Windows.
#
# Cuatro cosas, todas reproducidas y verificadas aqui antes de mandartelo:
#
#  1. UnicodeEncodeError EN WINDOWS (bug mio, el que acabas de ver).
#     Las herramientas imprimen bloques de grafico y simbolos de estado, y la
#     consola de Windows usa cp1252, que no puede representarlos. El script
#     hacia el trabajo y reventaba al contarlo. Las 10 herramientas fuerzan
#     ahora UTF-8 en su salida.
#
#  2. FICHERO QUE FALTA. deploy/elastic/consultas/cti_y_caza.txt no llego al
#     repositorio: es el unico SIEM con la carpeta de consultas vacia, y por
#     eso validate.py --estricto fallaba.
#
#  3. COMPROBACION FRAGIL (bug mio). validate.py miraba FECHAS de modificacion
#     para saber si el nodo de Shuffle estaba al dia. git no conserva mtimes,
#     asi que en un clon limpio dependia del orden del checkout: fallaba en CI
#     y pasaba en local. Ahora compara contenido.
#
#  4. LAS 14 REGLAS SUPERADAS. Cada una es subconjunto estricto de otra que
#     sigue en la biblioteca; con las dos presentes disparan a la vez sobre el
#     mismo evento. El razonamiento por regla esta en
#     docs/fusion-de-bibliotecas.md.
#
# Uso, desde la raiz del repositorio:
#     powershell -ExecutionPolicy Bypass -File .\arreglar.ps1

$ErrorActionPreference = 'Stop'

if (-not (Test-Path 'tools/build.py')) {
    Write-Error "Ejecutalo desde la raiz del repositorio (donde esta la carpeta tools)."
    exit 1
}

# Por si la consola de esta sesion tampoco puede con UTF-8.
try { [Console]::OutputEncoding = [Text.Encoding]::UTF8 } catch {}

$ficheros = @(
    @{ Ruta = 'tools/build.py'; B64 = '' }
    @{ Ruta = 'tools/generar_catalogo.py'; B64 = '' }
    @{ Ruta = 'tools/generar_cobertura_svg.py'; B64 = '' }
    @{ Ruta = 'tools/generar_enrutador.py'; B64 = '' }
    @{ Ruta = 'tools/mapear_marcos.py'; B64 = '' }
    @{ Ruta = 'tools/sigma_to_wazuh.py'; B64 = '' }
    @{ Ruta = 'tools/stamp_sigma_ids.py'; B64 = '' }
    @{ Ruta = 'tools/sync_cti.py'; B64 = '' }
    @{ Ruta = 'tools/validar_respuesta.py'; B64 = '' }
    @{ Ruta = 'tools/validate.py'; B64 = '' }
    @{ Ruta = 'deploy/elastic/consultas/cti_y_caza.txt'; B64 = '' }
)

Write-Host "1/4  Escribiendo herramientas corregidas y el fichero que faltaba"
foreach ($f in $ficheros) {
    $destino = Join-Path $PWD $f.Ruta
    $carpeta  = Split-Path $destino -Parent
    if (-not (Test-Path $carpeta)) { New-Item -ItemType Directory -Force -Path $carpeta | Out-Null }
    [IO.File]::WriteAllBytes($destino, [Convert]::FromBase64String($f.B64))
}
Write-Host "     $($ficheros.Count) ficheros"

Write-Host "2/4  Retirando las 14 reglas superadas"
$reglas = @(
    'rules/windows/proc_bitsadmin_transfer.yml'
    'rules/windows/proc_certutil_download_decode.yml'
    'rules/windows/proc_defender_tamper.yml'
    'rules/windows/proc_lsass_comsvcs_minidump.yml'
    'rules/windows/proc_mimikatz_cmdline.yml'
    'rules/windows/proc_mshta_execution.yml'
    'rules/windows/proc_powershell_download_cradle.yml'
    'rules/windows/proc_powershell_encoded.yml'
    'rules/windows/proc_regsvr32_scriptlet.yml'
    'rules/windows/proc_scheduled_task_create.yml'
    'rules/windows/proc_vssadmin_delete_shadows.yml'
    'rules/windows/proc_wevtutil_clear_logs.yml'
    'rules/windows/reg_run_key_persistence.yml'
    'rules/red/soc_net_004_explotacion_web.yml'
)
git rm -q --ignore-unmatch @reglas

Write-Host "3/4  Regenerando el contenido derivado"
foreach ($paso in 'tools/mapear_marcos.py',
                  'tools/build.py',
                  'tools/generar_enrutador.py',
                  'tools/validate.py') {
    python $paso | Out-Null
    if ($LASTEXITCODE -ne 0) {
        Write-Host ""
        Write-Host "Fallo $paso. Salida completa:"
        python $paso
        exit 1
    }
}

Write-Host "4/4  Commit"
Remove-Item -Force -ErrorAction SilentlyContinue arreglar.ps1
git add -A
git commit -q -m @"
Arreglar el CI y la ejecucion en Windows

- Las 10 herramientas fuerzan UTF-8 en su salida. La consola de Windows usa
  cp1252 y no puede imprimir los bloques del grafico de tacticas ni los
  simbolos de estado: validate.py hacia el trabajo y moria con
  UnicodeEncodeError al imprimir el informe.
- Restaura deploy/elastic/consultas/cti_y_caza.txt, que no habia llegado al
  repositorio y hacia fallar validate.py --estricto.
- validate.py comparaba fechas de modificacion para saber si el nodo de
  Shuffle estaba al dia. git no conserva mtimes, asi que el resultado dependia
  del orden del checkout: fallaba en CI y pasaba en local. Ahora compara el
  contenido de la tabla.
- Retira las 14 reglas que eran subconjunto estricto de otra que sigue en la
  biblioteca; con las dos presentes disparaban a la vez sobre el mismo evento.

127 reglas Sigma, 71 tecnicas ATT&CK base, 13 tacticas.
"@

$n = (Get-ChildItem -Path rules -Recurse -Filter *.yml).Count
Write-Host ""
if ([string]::IsNullOrWhiteSpace((git status --porcelain))) {
    Write-Host "Listo. $n reglas, arbol limpio. Ya puedes hacer: git push"
} else {
    Write-Host "QUEDAN CAMBIOS SIN COMMITEAR:"
    git status --short
    exit 1
}